            v[6] = 4.89663865010925e-12 * v[5];
            v[7] = v[2] * v[4] + v[1] * v[6];
            y[28] = -0.12 * v[7];
            v[6] = v[0] * v[4] + v[2] * v[6];
            y[29] = -0.12 * v[6];
            v[4] = -1. * v[5];
            y[30] = 0.333 + -0.12 * v[4];
            y[32] = -0.17 * v[7];
            y[33] = -0.17 * v[6];
            y[34] = 0.333 + -0.17 * v[4];
